import { z } from "zod";

const LicaoSchema = z.object({
  titulo: z.string(),
  xp: z.number(),
});

type Licao = z.infer<typeof LicaoSchema>;

const licao = LicaoSchema.parse({ titulo: "Intro", xp: 20 });
const resultado = LicaoSchema.safeParse({ titulo: "Intro" });

